def boundary(root):
    if root is None:
        return []

    def is_leaf(node):
        return node.left is None and node.right is None

    result = [root.val]
    if is_leaf(root):
        return result

    node = root.left
    while node:
        if not is_leaf(node):
            result.append(node.val)
        node = node.left if node.left else node.right

    def leaves(node):
        if node is None:
            return
        if is_leaf(node):
            result.append(node.val)
            return
        leaves(node.left)
        leaves(node.right)

    leaves(root)

    right_edge = []
    node = root.right
    while node:
        if not is_leaf(node):
            right_edge.append(node.val)
        node = node.right if node.right else node.left
    result.extend(reversed(right_edge))
    return result

