def top_view(root):
    if root is None:
        return []
    first = {}
    queue = deque([(root, 0)])
    while queue:
        node, col = queue.popleft()
        if col not in first:
            first[col] = node.val
        if node.left:
            queue.append((node.left, col - 1))
        if node.right:
            queue.append((node.right, col + 1))
    return [first[col] for col in sorted(first)]

