def side_views(root):
    right, left = [], []

    def visit(node, depth):
        if node is None:
            return
        if depth == len(left):
            left.append(node.val)
            right.append(node.val)
        right[depth] = node.val
        visit(node.left, depth + 1)
        visit(node.right, depth + 1)

    visit(root, 0)
    return [right, left]

