def distance_k(root, target, k):
    parent = {}
    start = None
    stack = [root]
    while stack:
        node = stack.pop()
        if node.val == target:
            start = node
        for child in (node.left, node.right):
            if child:
                parent[child] = node
                stack.append(child)
    seen = {start}
    frontier = [start]
    for _ in range(k):
        nxt = []
        for node in frontier:
            for other in (node.left, node.right, parent.get(node)):
                if other and other not in seen:
                    seen.add(other)
                    nxt.append(other)
        frontier = nxt
    return sorted(node.val for node in frontier)

def burn_time(root, start):
    parent = {}
    origin = None
    stack = [root]
    while stack:
        node = stack.pop()
        if node.val == start:
            origin = node
        for child in (node.left, node.right):
            if child:
                parent[child] = node
                stack.append(child)
    seen = {origin}
    frontier = [origin]
    seconds = 0
    while True:
        nxt = []
        for node in frontier:
            for other in (node.left, node.right, parent.get(node)):
                if other and other not in seen:
                    seen.add(other)
                    nxt.append(other)
        if not nxt:
            return seconds
        frontier = nxt
        seconds += 1

def count_nodes(root):
    if root is None:
        return 0
    left_depth = right_depth = 0
    node = root
    while node:
        left_depth += 1
        node = node.left
    node = root
    while node:
        right_depth += 1
        node = node.right
    if left_depth == right_depth:
        return (1 << left_depth) - 1
    return 1 + count_nodes(root.left) + count_nodes(root.right)

